      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "O apêndice apresenta a previsão de filtração profunda axi-simétrica de suspensão de partículas em solução aquosa, na presença de óleo residual, por meio de balanço de massa, cinética de captura e lei de Darcy modificada.",
          "trechos": [
            "E73931ee6aa46f541:700:1394"
          ],
          "condicoes": [
            "aplica-se ao modelo unidimensional axi-simétrico descrito",
            "considera suspensão de partículas em solução aquosa",
            "inclui presença de óleo residual"
          ],
          "limites": [
            "o trecho é de formulação/modelagem e não traz procedimento operacional de filtração em FPSO",
            "não informa especificações de filtros, retrolavagem ou limites de sólidos"
          ]
        },
        {
          "proposicao": "No modelo adimensionalizado, o contorno externo é tomado como meia-distância entre injetor e produtor e a taxa inicial de injeção é usada como referência, mostrando que a previsão de injetividade depende das hipóteses geométricas e de escala adotadas.",
          "trechos": [
            "E73931ee6aa46f541:1394:2016"
          ],
          "condicoes": [
            "vale para a formulação adimensional apresentada",
            "depende da definição de raio de contorno e da taxa inicial de injeção"
          ],
          "limites": [
            "o trecho não demonstra validação experimental nesse recorte",
            "as equações aparecem parcialmente ilegíveis, impedindo reconstrução completa dos parâmetros"
          ]
        }
      ]
    },
    {
