          ],
          "limites": [
            "os símbolos e números associados aos modelos estão incompletos",
            "o trecho não fornece método operacional para medir ou controlar essa transição em campo"
          ]
        },
        {
          "proposicao": "Nas recomendações do trabalho, o autor indica a necessidade de mais experimentos laboratoriais e de medir o perfil de deposição de partículas no meio poroso para melhorar o entendimento do dano à formação e da perda de injetividade.",
          "trechos": [
            "Ea09987f5b145ed57:700:1393",
            "Ea09987f5b145ed57:1393:2092"
          ],
          "condicoes": [
            "trata-se de recomendações do autor para continuidade de pesquisa"
          ],
          "limites": [
